qualifier.query:
WITH rp AS (
    SELECT *
    FROM read_parquet('{{this.FileName}}')
    ORDER BY time, name
    LIMIT {{this.Limit}} OFFSET {{this.Offset}}
)
SELECT  *
FROM rp
ORDER BY rp.time, rp.name;

